import numpy as np
print(np.average(np.arange(1, 5)), np.average(np.arange(1, 11), weights=np.arange(10, 0, -1)))
d = np.arange(6).reshape((3, 2))
print(np.average(d, axis=1, weights=[1. / 4, 3. / 4]), np.average(d, axis=0, returned=True), np.average(d, weights=d, axis=1, returned=True))
x = np.array([[0, 2], [1, 1], [2, 0]]).T
print(np.cov(x), np.cov([-2.1, -1, 4.3]), np.cov([-2.1, -1, 4.3], [3, 1.1, 0.12]), np.cov(x, bias=True), np.cov(x, aweights=[1, 2, 1]))
print(np.corrcoef([[1, 2, 3, 4], [2, 4, 6, 9], [5, 1, 0, 2]]))
print(np.trapezoid([1, 2, 3]), np.trapezoid([1, 2, 3], x=[4, 6, 8]), np.trapezoid([1, 2, 3], dx=2), np.trapezoid(np.arange(6).reshape(2, 3), axis=0))
f = np.array([1, 2, 4, 7, 11, 16])
print(np.gradient(f), np.gradient(f, 2), np.gradient(f, np.array([0., 1., 1.5, 3.5, 4., 6.])), np.gradient(f, edge_order=2))
print(np.gradient(np.array([[1, 2, 6], [3, 4, 5]])), np.gradient(np.array([[1, 2, 6], [3, 4, 5]]), axis=0))
print(np.sinc(np.linspace(-2, 2, 5)), np.sinc(0))
print(np.unwrap([0, 1, 2 * np.pi + 2, 3]), np.unwrap([0, 1, 2, -1, 0], period=4), np.unwrap([2, 3, 4, 5, 2, 3, 4, 5], period=4))
print(np.vander(np.array([1, 2, 3, 5])), np.vander(np.array([1, 2, 3, 5]), 3, increasing=True), np.vander([1.5, 2]))
print(np.i0(0.), np.i0([0, 1, 2, 3]), np.i0(np.array([5.0, 10.0, 20.0])))
print(np.bartlett(5), np.blackman(5), np.hamming(5), np.hanning(5), np.kaiser(5, 14), np.hanning(1), np.hanning(0))
print(np.correlate([1, 2, 3], [0, 1, 0.5]), np.correlate([1, 2, 3], [0, 1, 0.5], "same"), np.correlate([1, 2, 3], [0, 1, 0.5], "full"), np.correlate([0, 1, 0.5], [1, 2, 3], "full"))
print(np.convolve([1, 2, 3], [0, 1, 0.5]), np.convolve([1, 2, 3], [0, 1, 0.5], 'same'), np.convolve([1, 2, 3], [0, 1, 0.5], 'valid'), np.convolve([1, 2], [1, 2, 3, 4]))
print(np.histogram([1, 2, 1], bins=[0, 1, 2, 3]), np.histogram(np.arange(4), bins=np.arange(5), density=True), np.histogram([[1, 2, 1], [1, 0, 1]], bins=[0, 1, 2, 3]))
print(np.histogram(np.array([1, 2, 1, 4, 5]), bins=4), np.histogram(np.array([0.5, 1.5, 2.25, 9.0]), bins=3, range=(0, 3)), np.histogram(np.array([1, 2, 3]), weights=np.array([0.5, 1, 2]), bins=2))
rng = np.linspace(0, 10, 50) ** 1.5
print(np.histogram_bin_edges(rng, bins='auto'), np.histogram_bin_edges(rng, bins='sturges'), np.histogram_bin_edges(rng, bins='fd'))
print(np.histogram_bin_edges(rng, bins='rice'), np.histogram_bin_edges(rng, bins='scott'), np.histogram_bin_edges(rng, bins='sqrt'), np.histogram_bin_edges(rng, bins='doane'))
print(np.histogram(rng, bins='stone')[0])
H, xe, ye = np.histogram2d([1, 2, 3, 1], [4, 5, 6, 4], bins=2)
print(H, xe, ye)
print(np.histogramdd(np.array([[0, 0], [1, 1], [2, 1.5]]), bins=(2, 3)))
print(np.digitize(np.array([0.2, 6.4, 3.0, 1.6]), np.array([0.0, 1.0, 2.5, 4.0, 10.0])), np.digitize(np.array([1.2, 10.0, 12.4, 15.5, 20.]), np.array([0, 5, 10, 15, 20]), right=True))
print(np.digitize([1, 5, 9], [10, 5, 0]))
print(np.frexp(np.arange(9)), np.frexp(8.0), np.ldexp(5, np.arange(4)), np.ldexp(np.float32(1.5), 3), np.modf([0, 3.5]), np.modf(-0.5), np.divmod(np.arange(5), 3))
print(np.iscomplex([1, 2]), np.isreal([1, 2.5]), np.real_if_close([2.1, 5.2]), np.isposinf([np.inf, -np.inf, 1.0]), np.isneginf(-np.inf))
print(np.nanargmax([[np.nan, 4], [2, 3]]), np.nanargmin([[np.nan, 4], [2, 3]], axis=1), np.nanargmax(np.array([[np.nan, 4], [2, 3]]), axis=0))
a = np.array([[10.0, 7, 4], [3, 2, 1]])
a[0, 1] = np.nan
print(np.nanmedian(a), np.nanmedian(a, axis=0), np.nanmedian(a, axis=1), np.nanmedian(a, axis=1, keepdims=True), np.nanmedian(np.array([1.0, 2.0])))
print(np.nanpercentile(a, 50), np.nanpercentile(a, 50, axis=0), np.nanquantile(a, 0.5, axis=1), np.nanpercentile(a, [25, 75], axis=1))
